insert into lightdey.sources (id, name, kind, trust_tier, coverage, url, credentials_required, refresh_interval_minutes, is_active, notes) values
  ('niso_niggrid', 'NISO Grid Data Portal (NIGGRID)', 'official_grid', 1, 'National grid; per-DisCo load allocation (incl. Eko and Ikeja DisCos)', 'https://www.niggrid.org/DisCoLoadProfile', false, 10, true, 'Public page, no login, no robots.txt (pages carry noindex). Fetched at most every 10 minutes with an identifying User-Agent. Kill switch: SOURCE_NISO_ENABLED=0.'),
  ('ikeja_electric_notices', 'Ikeja Electric public notices (RSS)', 'official_disco', 1, 'Ikeja Electric franchise area (northern Lagos)', 'https://www.ikejaelectric.com/feed/', false, 60, true, 'Official RSS feed intended for syndication. robots.txt Crawl-delay 10 is respected by fetching once an hour. Kill switch: SOURCE_IKEJA_NOTICES_ENABLED=0.'),
  ('eko_disco_notices', 'Eko Electricity Distribution (EKEDP) notices', 'official_disco', 1, 'Eko DisCo franchise area (southern Lagos)', 'https://ekedp.com/', false, null, false, 'No machine-readable feed found (ekedp.com/feed returns 404, checked 2026-11-13). Would need a partner feed or the X API.'),
  ('x_disco_accounts', 'DisCo / TCN / NISO posts on X', 'official_disco', 1, 'Lagos DisCos, TCN, NISO', 'https://developer.x.com/', true, null, false, 'Reading posts requires a paid X API plan. Not implemented until credentials exist.'),
  ('light_dey_sensor', 'Light Dey Sensor (opt-in mains-detection devices)', 'telemetry', 1, 'The neighbourhood each device is registered to (no address or precise location)', null, true, 1, true, 'Protocol v1 (HTTP, HMAC-signed, replay- and rate-limited) implemented and tested; reference Raspberry Pi client in scripts/sensor/. No devices deployed yet.'),
  ('ioda', 'IODA internet connectivity (Georgia Tech) — Lagos region', 'proxy', 4, 'Lagos State as a whole (region 2935) — too coarse for neighbourhoods', 'https://api.ioda.inetintel.cc.gatech.edu/v2/', true, 15, true, 'API publicly reachable and verified 2026-11-14 (region 2935 ''Lagos'', 10-min signals, outage events). Adapter implemented but OFF unless SOURCE_IODA_ENABLED=1 after permission is granted.'),
  ('victron_vrm', 'Victron VRM (inverter monitoring) — opt-in installations', 'device_provider', 1, 'Per consenting installation', 'https://vrm-api-docs.victronenergy.com/', true, null, false, 'Not implemented and not claimed compatible until tested with a real consenting installation (LD-074).'),
  ('shelly_cloud', 'Shelly Cloud (smart plugs / relays) — opt-in devices', 'device_provider', 1, 'Per consenting device', 'https://shelly-api-docs.shelly.cloud/', true, null, false, 'Not implemented and not claimed compatible until tested (LD-075).'),
  ('tcn_website', 'Transmission Company of Nigeria website', 'official_grid', 1, 'National transmission', 'https://www.tcn.org.ng/', false, null, false, 'Rejected: no outage/disturbance feed.'),
  ('laserc', 'Lagos State Electricity Regulatory Commission', 'regulator', 1, 'Lagos State', null, false, null, false, 'Rejected for now: unreachable. Revisit if a public notices channel appears.'),
  ('scraped_signals', 'Downdetector, Google ''popular times'', road cameras, social posts', 'proxy', 4, 'Varies', null, false, null, false, 'Rejected: inaccessible lawfully, unverifiable, or too coarse.'),
  ('partner_feed', 'Verified partners (businesses, security desks, facilities, community organisations)', 'verified_partner', 2, 'Per partner agreement', null, true, null, false, 'Ingestion API implemented; no partners approved yet.'),
  ('verified_reporters', 'Verified community reporters', 'verified_reporter', 2, 'Per reporter''s home neighbourhood', null, true, null, false, 'No reporters verified yet. Each vetted person gets their own source (verified:<slug>) so independent reporters are counted separately; this row is the public label and never holds keys. Account-based verification arrives with sign-in (LD-014).'),
  ('community', 'Light Dey? community reports', 'community', 3, 'All supported Lagos neighbourhoods', null, false, null, true, 'Submitted at /report and on each area page.'),
  ('nerc_reports', 'NERC quarterly & energy-cap reports', 'regulator', 1, 'National, per DisCo, per feeder (monthly/quarterly)', 'https://nerc.gov.ng/', false, null, false, 'PDF publications only.'),
  ('historical_estimate', 'Historical pattern estimate', 'estimate', 4, 'Areas with enough confirmed community history', null, false, 60, true, 'Computed from stored community history only.')
